import asyncio
from contextlib import asynccontextmanager
class Admission:
  def __init__(self, limit: int) -> None:
     self._slots = asyncio.Semaphore(limit)
     self.in_flight = 0
     self.rejected = 0
  @asynccontextmanager
  async def slot(self, wait_s: float = 5.0):
     try:
        await asyncio.wait_for(self._slots.acquire(), timeout=wait_s)
     except TimeoutError:
        self.rejected += 1
        raise OverflowError("queue_full") from None
     self.in_flight += 1
     try:
        yield
     finally:
        self.in_flight -= 1
        self._slots.release()

